package com.sporthub.payment;
import static org.assertj.core.api.Assertions.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import java.sql.*;
import java.util.UUID;
class RefundReviewMigrationTest {
 @Test void upgradeUsesActualPayerWhenLegacyRequestWasOpenedByAdmin()throws Exception{check(false);}
 @Test void unsupportedLegacyRefundStopsUpgradeAndPreservesEvidence()throws Exception{check(true);}
 private void check(boolean inconsistent)throws Exception{String url=System.getenv("SPORTHUB_PAYMENT_TEST_DB_URL"),user=System.getenv("SPORTHUB_TEST_DB_USER"),password=System.getenv("SPORTHUB_TEST_DB_PASSWORD");org.testcontainers.containers.PostgreSQLContainer<?> pg=null;if(url==null){pg=new org.testcontainers.containers.PostgreSQLContainer<>("postgres:16-alpine");pg.start();url=pg.getJdbcUrl();user=pg.getUsername();password=pg.getPassword();}try{String schema="refund_upgrade_"+UUID.randomUUID().toString().replace("-","");Flyway.configure().dataSource(url,user,password).schemas(schema).defaultSchema(schema).target("8").load().migrate();try(var c=DriverManager.getConnection(url,user,password);var s=c.createStatement()){s.execute("SET search_path TO "+schema+",public");UUID booking=UUID.randomUUID(),payer=UUID.randomUUID(),admin=UUID.randomUUID(),payment=UUID.randomUUID();s.execute("INSERT INTO payment_obligations(booking_id,purpose,subject_id,amount,currency) VALUES('"+booking+"','BOOKING','00000000-0000-0000-0000-000000000000',100000,'VND')");s.execute("INSERT INTO payment_orders(id,booking_id,payer_id,purpose,amount,currency,provider,provider_reference,status,idempotency_key,expires_at,paid_at) VALUES('"+payment+"','"+booking+"','"+payer+"','BOOKING',100000,'VND','DEMO','legacy-refund','SUCCESS','legacy-refund',NOW()+interval '10 minutes',NOW())");s.execute("INSERT INTO refunds(id,payment_id,requester_id,reason,state,amount,idempotency_key) VALUES(gen_random_uuid(),'"+payment+"','"+admin+"','Legacy admin review','"+(inconsistent?"SUCCESS":"BLOCKED_RULE")+"',"+(inconsistent?"100000":"NULL")+",'legacy-admin')");var latest=Flyway.configure().dataSource(url,user,password).schemas(schema).defaultSchema(schema).load();if(inconsistent){assertThatThrownBy(latest::migrate).hasMessageContaining("Refund review preflight failed");try(var r=s.executeQuery("SELECT state,amount FROM refunds")){r.next();assertThat(r.getString(1)).isEqualTo("SUCCESS");assertThat(r.getBigDecimal(2)).isEqualByComparingTo("100000");}}else{latest.migrate();latest.validate();try(var r=s.executeQuery("SELECT beneficiary_id,requester_id,state,amount FROM refunds")){r.next();assertThat(r.getObject(1,UUID.class)).isEqualTo(payer);assertThat(r.getObject(2,UUID.class)).isEqualTo(admin);assertThat(r.getString(3)).isEqualTo("BLOCKED_RULE");assertThat(r.getBigDecimal(4)).isNull();}try(var r=s.executeQuery("SELECT count(*) FROM refund_review_notes")){r.next();assertThat(r.getInt(1)).isZero();}assertThatThrownBy(()->s.execute("UPDATE refunds SET beneficiary_id=gen_random_uuid()")).isInstanceOf(SQLException.class);}}}finally{if(pg!=null)pg.stop();}}
}
